async function run(
  args: string[],
  ctx: LooseRecord = {},
): Promise<number> {
  if (args.includes("--help") || args.includes("-h")) {
    printHelp();
    return 0;
  }

  // Parse flags: --project <id> | --project=<id> | -p <id>; first positional is
  // the task id. Remaining positionals are ignored (the public surface takes a
  // single task id).
  let project = "";
  const positional: string[] = [];
  for (let i = 0; i < args.length; i++) {
    const arg = args[i];
    if (arg === "--project" || arg === "-p") {
      if (i + 1 < args.length) {
        project = args[++i];
      }
    } else if (arg.startsWith("--project=")) {
      project = arg.slice("--project=".length);
    } else {
      positional.push(arg);
    }
  }
  const taskId = positional[0] || "";

  if (!taskId) {
    console.error("Usage: cpb task <task-id> [--project <id>]");
    return 1;
  }

  const cpbRoot = ctx.cpbRoot || process.env.CPB_ROOT || process.cwd();

  if (!project) {
    project = await autoResolveProject(cpbRoot);
  }

  // Reuse the Wave 1 projection — no new state machine, no duplicated pipeline.
  const { projectTaskView } = await import("../../server/services/task/task-view.js");
  const view: TaskView | null = await projectTaskView(cpbRoot, project, taskId);

  if (!view) {
    // Plain message; no internal terms. The caller already holds the id, so we
    // do not echo secrets — just confirm the miss.
    console.error(`No task found with id "${taskId}".`);
    return 1;
  }

  renderTaskView(view);
  return 0;
}

async function autoResolveProject(cpbRoot: string): Promise<string> {
  // 1. Registered project whose source path covers cwd.
  try {
    const { resolveHubRoot, loadRegistry } = await import(
      "../../server/services/hub/hub-registry.js"
    );
    const hubRoot = resolveHubRoot(cpbRoot);
    const registry = await loadRegistry(hubRoot);
    const cwd = path.resolve(process.cwd());
    const projects = (registry?.projects || {}) as Record<string, LooseRecord>;
    for (const [id, proj] of Object.entries(projects)) {
      const src = proj?.sourcePath ? path.resolve(String(proj.sourcePath)) : null;
      if (src && (src === cwd || cwd.startsWith(src + path.sep))) {
        return id;
      }
    }
  } catch {
    // fall through to the next strategy
  }

  // 2. package.json name in cwd.
  try {
    const pkgRaw = await readFile(path.join(process.cwd(), "package.json"), "utf8");
    const pkg = JSON.parse(pkgRaw) as { name?: unknown };
    if (typeof pkg.name === "string" && pkg.name) {
      const derived = pkg.name.replace(/[^a-zA-Z0-9-]/g, "-").replace(/^-+|-+$/g, "");
      if (derived) return derived;
    }
  } catch {
    // fall through
  }

  // 3. Directory basename.
  const fallback = path
    .basename(process.cwd())
    .replace(/[^a-zA-Z0-9-]/g, "-")
    .replace(/^-+|-+$/g, "");
  return fallback || "default";
}

function renderTaskView(view: TaskView): void {
  const rawSummary = typeof view.summary === "string" ? view.summary.trim() : "";
  const summary = rawSummary || "(no description given)";
  const stateLine = humanStateLine(view.state);
  const progressLabel =
    view.progress && typeof view.progress.label === "string"
      ? view.progress.label.trim()
      : "";
  const nextStep = humanNextStep(view.nextAction);
  const resultLine = humanResultLine(view);

  const lines: string[] = [];
  lines.push(summary);
  lines.push("");
  lines.push(`State:    ${stateLine}`);
  if (resultLine) lines.push(`Result:   ${resultLine}`);
  if (progressLabel) lines.push(`Progress: ${progressLabel}`);
  lines.push(`Next:     ${nextStep}`);
  console.log(lines.join("\n"));
}

async function projectTaskView(
  cpbRoot: string,
  project: string,
  taskId: string,
  opts: { dataRoot?: string; hubRoot?: string } = {},
): Promise<TaskView | null> {
  if (typeof taskId !== "string" || !taskId) return null;

  // 1. Resolve hub root and read the durable queue.
  const hubRoot = opts.hubRoot ? opts.hubRoot : resolveHubRoot(cpbRoot);
  const queue = await loadQueue(hubRoot);
  const entries: unknown = (queue as LooseRecord)?.entries;
  const entryList: LooseRecord[] = Array.isArray(entries)
    ? entries.filter((e) => isRecord(e))
    : [];
  // Match by id WITHIN THIS PROJECT ONLY. A cross-project id-only fallback
  // would let a caller scoped to project A read project B's task by supplying
  // B's task id — a project-isolation / authorization boundary violation
  // (plan §3.2: taskId is the project-scoped opaque queue entry id). If the id
  // is not found in this project, return null rather than searching others.
  const entry =
    entryList.find((e) => stringValue(e.id) === taskId && stringValue(e.projectId) === project)
    || null;
  if (!entry) return null;

  // 2. Look up the job linked to this queue entry (if any). `getJobByQueueEntryId`
  //    returns null when no job exists yet — the queue-only branch handles that.
  let job: LooseRecord | null = null;
  try {
    const linked = await getJobByQueueEntryId(cpbRoot, project, taskId, {
      dataRoot: opts.dataRoot,
    });
    job = isRecord(linked) ? (linked as LooseRecord) : null;
  } catch {
    // A transient runtime read failure must not crash the read-only projection.
    // Fall back to queue-only state; the caller sees the queue's authoritative
    // status rather than an error.
    job = null;
  }

  // 3. Derive state. The job is authoritative when present (it carries verdict
  //    + completion gate evidence the queue does not). The queue entry is the
  //    authority for the pre-job window and for terminal delivery state.
  const projected = job
    ? deriveStateFromJob(job)
    : deriveStateFromQueueEntry(entry);

  // 4. Compute the Phase 2 evidence bundle. `verified` is the authoritative
  //    gate signal; `deliveryReady` layers the finalizer receipt on top. The
  //    bundle is consumed by every field builder so the three-way distinction
  //    is consistent across checks / progress / nextAction.
  const gate = extractGateEvidence(job);
  const receiptPresent = finalizerReceiptPresent(job, entry);
  const published = publicationProven(job);
  const deliveryReady = projected.verified && (receiptPresent || published);
  const evidence: ProjectedEvidence = {
    reachedTerminal: projected.reachedTerminal,
    verified: projected.verified,
    deliveryReady,
    published,
    gate,
  };

  // 5. Build the public fields. None of these copy forbidden fields verbatim —
  //    each is a deliberate, minimal derivation.
  const summary = buildSummary(entry, job);
  const progress = buildProgress(projected.state, gate);
  const checks = buildChecks(evidence);
  const changedFiles = buildChangedFiles(job);
  const nextAction = buildNextAction(projected.state, entry, job, evidence);

  const entryCreatedAt = stringValue(entry.createdAt);
  const entryUpdatedAt = stringValue(entry.updatedAt);
  const jobCreatedAt = stringValue(job?.createdAt);
  const jobUpdatedAt = stringValue(job?.updatedAt);
  const createdAt = entryCreatedAt || jobCreatedAt || nowIso();
  const updatedAt = latestIso(entryUpdatedAt, jobUpdatedAt) || createdAt;

  // 6. Compose, sanitize, and return. `sanitizeTaskView` is the frozen
  //    boundary enforcer — it strips any forbidden key that might have been
  //    introduced by future derivation changes. Today it is a no-op safety net.
  const raw: Record<string, unknown> = {
    schemaVersion: TASK_VIEW_SCHEMA_VERSION,
    taskId,
    state: projected.state,
    summary,
    progress,
    checks,
    changedFiles,
    nextAction,
    createdAt,
    updatedAt,
  };
  const sanitized = sanitizeTaskView(raw);
  return sanitized as unknown as TaskView;
}

async function loadQueue(hubRoot: string) {
  return await loadLocalQueue(hubRoot);
}

async function loadLocalQueue(hubRoot: string) {
  try {
    const raw = await readBoundedRegularFileNoFollow(queuePath(hubRoot), { maxBytes: QUEUE_MAX_BYTES });
    return normalizeQueue(JSON.parse(raw));
  } catch (err) {
    if (errnoCode(err) === "ENOENT") return defaultQueue();
    if (String(errnoCode(err)).startsWith("BOUNDED_FILE_")) {
      throw Object.assign(new Error(`unsafe local queue file: ${queuePath(hubRoot)}`, { cause: err }), {
        code: errnoCode(err) === "BOUNDED_FILE_TOO_LARGE" ? "HUB_QUEUE_TOO_LARGE" : "HUB_QUEUE_UNSAFE",
      });
    }
    throw err;
  }
}

Object.assign(new Error(`unsafe local queue file: ${queuePath(hubRoot)}`, { cause: err }), {
        code: errnoCode(err) === "BOUNDED_FILE_TOO_LARGE" ? "HUB_QUEUE_TOO_LARGE" : "HUB_QUEUE_UNSAFE",
      })

async function getJobByQueueEntryId(cpbRoot: string, project: string, queueEntryId: string, { dataRoot }: RuntimePathOptions = {}) {
  if (!queueEntryId) return null;
  const jobs = await listJobs(cpbRoot, { project, dataRoot });
  return jobs.find((job: JobState) => job.queueEntryId === queueEntryId) || null;
}

